<template><div><div class="page-head"><div><h1 class="page-title">意见反馈</h1><p class="page-subtitle">告诉我们使用中的问题或建议。</p></div></div><el-row :gutter="20"><el-col :xs="24" :md="10"><el-card class="soft-card" shadow="never"><template #header><b>提交反馈</b></template><el-input v-model="content" type="textarea" :rows="8" maxlength="500" show-word-limit placeholder="请填写你的反馈内容"/><el-button type="primary" :loading="submitting" class="submit-btn" @click="submit">提交反馈</el-button></el-card></el-col><el-col :xs="24" :md="14"><el-card class="soft-card" shadow="never"><template #header><b>我的反馈记录</b></template><div v-if="items.length" class="feedback-list"><div v-for="item in items" :key="item.id" class="feedback-item"><div><el-tag :type="item.status==='processed'?'success':item.status==='ignored'?'info':'warning'">{{ statusLabel(item.status) }}</el-tag><span class="date">{{ item.createdAt || '' }}</span></div><p>{{ item.content }}</p></div></div><el-empty v-else-if="!loading" description="还没有反馈记录"/></el-card></el-col></el-row></div></template>
<script setup>
import { onMounted, ref } from 'vue'; import { ElMessage } from 'element-plus'; import { listFeedback, submitFeedback } from '../api/feedback'; import { statusLabel } from '../utils/time'
const content=ref('');const items=ref([]);const loading=ref(false);const submitting=ref(false);async function load(){loading.value=true;try{const d=await listFeedback({page:1,size:20});items.value=d?.list||[]}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}async function submit(){if(!content.value.trim())return ElMessage.warning('请先填写反馈内容');if(submitting.value)return;submitting.value=true;try{await submitFeedback({content:content.value.trim()});content.value='';ElMessage.success('反馈提交成功');load()}catch(e){ElMessage.error(e.message)}finally{submitting.value=false}}onMounted(load)
</script>
<style scoped>.submit-btn{margin-top:16px;width:100%}.feedback-item{padding:14px 0;border-bottom:1px solid #edf2f2}.feedback-item p{margin:10px 0 0;color:#5e7077;line-height:1.7}.date{margin-left:12px;color:#9aa8ac;font-size:12px}</style>
